using System;using System.IO;using System.Net;using System.Net.Sockets;using System.Net.NetworkInformation;using System.Linq;using System.Text;using System.Threading;
sealed class LocalSetupServer:IDisposable {
 readonly TcpListener listener;readonly string route;readonly DateTime expires;readonly Thread worker;volatile bool stopped;public volatile bool GuideOpened;
 public readonly string Url;
 public static IPAddress LanAddress(){foreach(var nic in NetworkInterface.GetAllNetworkInterfaces()){if(nic.OperationalStatus!=OperationalStatus.Up||nic.NetworkInterfaceType==NetworkInterfaceType.Loopback||nic.NetworkInterfaceType==NetworkInterfaceType.Tunnel)continue;var ip=nic.GetIPProperties();if(!ip.GatewayAddresses.Any(g=>g.Address.AddressFamily==AddressFamily.InterNetwork&&!g.Address.Equals(IPAddress.Any)))continue;foreach(var unicast in ip.UnicastAddresses){if(unicast.Address.AddressFamily!=AddressFamily.InterNetwork)continue;var b=unicast.Address.GetAddressBytes();if(b[0]==10||(b[0]==192&&b[1]==168)||(b[0]==172&&b[1]>=16&&b[1]<=31))return unicast.Address;}}throw new Exception("Conecte o computador a uma rede local para gerar o QR.");}
 public LocalSetupServer(IPAddress address,int port){route="/setup/"+Guid.NewGuid().ToString("N");expires=DateTime.UtcNow.AddMinutes(10);listener=new TcpListener(address,port);listener.Start(8);Url="http://"+address+":"+((IPEndPoint)listener.LocalEndpoint).Port+route;worker=new Thread(Accept){IsBackground=true};worker.Start();}
 void Accept(){while(!stopped){try{var client=listener.AcceptTcpClient();ThreadPool.QueueUserWorkItem(_=>Serve(client));}catch{if(stopped)return;}}}
 void Serve(TcpClient client){using(client){try{client.ReceiveTimeout=2500;client.SendTimeout=2500;using(var stream=client.GetStream()){var buffer=new byte[4096];int read=stream.Read(buffer,0,buffer.Length);string request=Encoding.ASCII.GetString(buffer,0,read);var first=request.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).FirstOrDefault()??"";var parts=first.Split(' ');int status=404;string body="Página não encontrada.";if(DateTime.UtcNow>expires){status=410;body="O QR expirou. Gere outro no PhoneDeck.";}else if(parts.Length>=2&&parts[0]=="GET"&&parts[1]==route){status=200;body=Page;GuideOpened=true;}else if(parts.Length>0&&parts[0]!="GET"){status=405;body="Método não permitido.";}var content=Encoding.UTF8.GetBytes(body);var header=Encoding.ASCII.GetBytes("HTTP/1.1 "+status+" "+(status==200?"OK":"Unavailable")+"\r\nContent-Type: text/html; charset=utf-8\r\nContent-Length: "+content.Length+"\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\nContent-Security-Policy: default-src 'none'; style-src 'unsafe-inline'; frame-ancestors 'none'\r\nConnection: close\r\n\r\n");stream.Write(header,0,header.Length);stream.Write(content,0,content.Length);}}catch{}}}
 public bool Expired{get{return DateTime.UtcNow>expires;}}
 public void Dispose(){stopped=true;listener.Stop();}
 public const string Page=@"<!doctype html><html lang='pt-BR'><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Conectar celular · PhoneDeck</title><style>body{background:#0d1117;color:#e8eef6;font:16px system-ui;margin:0;padding:28px 20px}main{max-width:540px;margin:auto}b.logo{color:#3591f6;font-size:22px}h1{font-size:30px;line-height:1.15}p,li{color:#b1c0d2;line-height:1.65}.card{background:#141a23;border:1px solid #273140;border-radius:14px;padding:20px;margin:18px 0}h2{font-size:20px;color:#fff}small{color:#8697ae}.tag{color:#1eba84;font-size:13px}li{margin:12px 0}strong{color:#fff}</style><main><b class='logo'>P · PhoneDeck</b><h1>Seu celular no computador.</h1><p class='tag'>Guia local · sem conta, domínio ou app no celular</p><div class='card'><h2>1. Conecte pelo Bluetooth</h2><ol><li>No PC, abra Bluetooth pelo botão no PhoneDeck e escolha <strong>Adicionar dispositivo</strong>.</li><li>No celular, abra <strong>Ajustes/Configurações → Bluetooth</strong> e mantenha essa tela aberta.</li><li>Escolha o celular no PC. Compare os números e <strong>confirme o mesmo código nos dois aparelhos</strong>.</li></ol></div><div class='card'><h2>2. Permita chamadas e contatos</h2><p><strong>iPhone:</strong> toque no ⓘ ao lado do computador e habilite Sincronizar contatos, se disponível.</p><p><strong>Android:</strong> toque na engrenagem ao lado do computador e permita Chamadas e Compartilhamento de contatos, se disponíveis.</p></div><div class='card'><h2>3. Confira no PhoneDeck</h2><p>Volte ao computador para verificar o aparelho. Abrir este guia não conclui o pareamento nem concede permissão de telefonia.</p><p>O suporte a chamadas independentes do Vincular ao Celular ainda precisa ser validado na instalação. Bluetooth pareado não significa que o controle de chamadas foi liberado.</p></div><small>Esta página não recebe contatos, senhas ou comandos de ligação. Ela funciona enquanto o assistente no PC estiver aberto, por até 10 minutos. Computador e celular precisam estar na mesma rede Wi-Fi.</small></main></html>";
}
